const hoyStr = new Date().toISOString().slice(0, 10);

const reservas = $('Buscar Todas las Reservas').all()
  .filter(i => Object.keys(i.json).length > 0)
  .map(i => i.json);

const escalaciones = $('Buscar Todas las Escalaciones').all()
  .filter(i => Object.keys(i.json).length > 0)
  .map(i => i.json);

const reservasHoy = reservas.filter(b => String(b.createdAt || '').slice(0, 10) === hoyStr);
const confirmadasHoy = reservasHoy.filter(b => b.status === 'confirmada');
const pendientesHoy = reservasHoy.filter(b => b.status === 'pendiente_pago');
const totalIniciadas = confirmadasHoy.length + pendientesHoy.length;
const tasaConversion = totalIniciadas > 0 ? ((confirmadasHoy.length / totalIniciadas) * 100).toFixed(1) + '%' : 'N/A';
const ingresoHoy = confirmadasHoy.reduce((sum, b) => sum + (Number(b.totalUSD) || 0), 0);

const manana = new Date(); manana.setDate(manana.getDate() + 1);
const mananaStr = manana.toISOString().slice(0, 10);
const toursDeManana = reservas.filter(b => b.status === 'confirmada' && String(b.date || '').slice(0, 10) === mananaStr);

const escalacionesHoy = escalaciones.filter(e => String(e.createdAt || '').slice(0, 10) === hoyStr);
const escalacionesTotalAbiertas = escalaciones.length;

const LF = String.fromCharCode(10);
const mensaje = [
  '📊 Reporte Diario Operativo — Costa Rica Tours',
  '📅 Fecha: ' + hoyStr,
  '',
  '• Reservas confirmadas: ' + confirmadasHoy.length,
  '• Reservas pendientes: ' + pendientesHoy.length,
  '• Tasa de Conversión: ' + tasaConversion,
  '• Ingresos generados hoy: $' + ingresoHoy.toFixed(2) + ' USD',
  '• Tours programados para mañana: ' + toursDeManana.length,
  '',
  '• Operadores oficiales: Alsama Tours CR / Expediciones Tropicales',
  '• Escalaciones del día: ' + escalacionesHoy.length,
  '• Total histórico de escalaciones: ' + escalacionesTotalAbiertas,
  '',
  '🌿 Operación en regla y sincronizada con n8n Cloud'
].join(LF);

return [{ json: { mensaje, confirmadasHoy: confirmadasHoy.length, tasaConversion, ingresoHoy, escalacionesHoy: escalacionesHoy.length } }];
